// Name:   PredefinedMethod /CheatGear/BasicTypes.FText.ToString
// Params:
//   ReturnValue                  0x000(0x000), 
std::string FText::ToString() const
{
    FString name = Get();
    if (!name.wc_str())
        return "NOT FOUND";

    size_t length = name.Num;
    std::string str(length, '\0');
    std::use_facet<std::ctype<wchar_t>>(std::locale()).narrow(name.wc_str(), name.wc_str() + length, '?', str.data());

    return str;
}

